<template>
  <div
    class="portfolio-shell"
    :class="[`track-${activeTrack}`, siteSlideClass, { 'past-hero': isPastHero, 'dual-layout': isWideDualLayout, 'mobile-track-gate': isMobileTrackGate, 'mobile-track-committed': mobileTrackCommitted }]"
    :style="siteSeamStyle"
    @pointermove="updateHeroSplit"
    @pointerdown="updateInteractionIntent"
    @touchstart="handleTouchStart"
    @touchmove="handleTouchMove"
    @touchend="handleTouchEnd"
    @touchcancel="resetTouchGesture"
    @wheel="handleWheel"
    @mouseleave="handleShellMouseLeave"
  >
    <nav class="site-edge-switch" aria-label="Portfolio story switcher">
      <button
        class="site-edge engineering-edge"
        type="button"
        @mouseenter="previewSlideTrack('engineering')"
        @focusin="previewSlideTrack('engineering')"
        @mouseleave="clearSlidePreview"
        @focusout="clearSlidePreview"
        @click="commitSlideTrack('engineering')"
      >
        <span>Engineering</span>
      </button>

      <button
        class="site-edge games-edge"
        type="button"
        @mouseenter="previewSlideTrack('games')"
        @focusin="previewSlideTrack('games')"
        @mouseleave="clearSlidePreview"
        @focusout="clearSlidePreview"
        @click="commitSlideTrack('games')"
      >
        <span>Games</span>
      </button>
    </nav>

    <div class="rail-wave" aria-hidden="true">
      <svg viewBox="0 0 120 1000" preserveAspectRatio="none">
        <defs>
          <linearGradient id="rail-wave-gradient" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stop-color="#d19f39" />
            <stop offset="48%" stop-color="#d19f39" />
            <stop offset="52%" stop-color="#d84f45" />
            <stop offset="100%" stop-color="#d84f45" />
          </linearGradient>
        </defs>
        <path class="rail-wave-shadow" d="M60 -8 C 38 94, 76 185, 54 302 C 31 426, 80 531, 58 656 C 39 762, 74 866, 52 1008" />
        <path class="rail-wave-core" d="M60 -8 C 38 94, 76 185, 54 302 C 31 426, 80 531, 58 656 C 39 762, 74 866, 52 1008" />
        <path class="rail-wave-glint" d="M60 -8 C 38 94, 76 185, 54 302 C 31 426, 80 531, 58 656 C 39 762, 74 866, 52 1008" />
      </svg>
    </div>

    <div class="site-stack">
    <main
      v-for="trackId in trackIds"
      :key="trackId"
      class="site-plane"
      :class="planeClass(trackId)"
    >
      <section class="hero-section">
      <div class="hero-media" aria-hidden="true">
        <img src="/images/landing/landing-backdrop-new.png" alt="">
        <div class="hero-grid"></div>
      </div>

      <div
        class="dual-hero rail-hero"
        :class="heroModeClass"
      >
        <article
          class="story-side engineering-story"
          :class="{ active: heroHoverTrack === 'engineering' }"
          tabindex="0"
          @mouseenter="previewTrack('engineering')"
          @focusin="previewTrack('engineering')"
          v-show="trackId === 'engineering'"
        >
          <div class="story-inner">
            <p class="mono-label">Kaz Voeten / Engineering track</p>
            <h1>Software, Systems<br>&amp; AI Engineer</h1>
            <p class="story-copy">
              Backend services, AI interaction systems, and product tooling shaped by design intent and production constraints.
            </p>
            <div class="story-credentials">
              <span v-for="item in tracks.engineering.credentials.slice(0, 3)" :key="item.value">{{ item.value }}</span>
            </div>
            <button class="primary-action" type="button" @click="exploreTrack('engineering')">
              Explore engineering work
            </button>
          </div>
        </article>

        <article
          class="story-side games-story"
          :class="{ active: heroHoverTrack === 'games' }"
          tabindex="0"
          @mouseenter="previewTrack('games')"
          @focusin="previewTrack('games')"
          v-show="trackId === 'games'"
        >
          <div class="story-inner">
            <p class="mono-label">Kaz Voeten / Game track</p>
            <h1>Technical Designer<br>Systems Lead</h1>
            <p class="story-copy">
              AAA production systems, Unreal C++, shipped VR products, and design-to-implementation leadership.
            </p>
            <div class="story-credentials">
              <span v-for="item in tracks.games.credentials.slice(0, 3)" :key="item.value">{{ item.value }}</span>
            </div>
            <button class="primary-action" type="button" @click="exploreTrack('games')">
              Explore game systems
            </button>
          </div>
        </article>

      </div>
      </section>

      <section class="credential-section">
      <div v-for="item in trackData(trackId).credentials" :key="item.value" class="credential-tile">
        <strong>{{ item.value }}</strong>
        <span>{{ item.label }}</span>
      </div>
      </section>

      <section :id="trackId === activeTrack ? 'featured' : null" class="content-section">
      <div class="section-heading">
        <p class="mono-label">{{ trackData(trackId).label }}</p>
        <h2>{{ trackData(trackId).title }}</h2>
        <p>{{ trackData(trackId).summary }}</p>
      </div>

      <div class="featured-grid">
        <article
          v-for="project in projectsForTrack(trackId)"
          :key="project.slug"
          class="project-card"
          :class="{ 'project-card-nda': project.isConfidential }"
        >
          <div class="project-image">
            <img :src="project.image" :alt="project.title">
            <div v-if="project.isConfidential" class="nda-card-overlay" aria-label="NDA protected project">
              <span class="lock-icon" aria-hidden="true"></span>
              <strong>NDA</strong>
            </div>
            <p v-if="project.imageCaption" class="image-caption">{{ project.imageCaption }}</p>
          </div>
          <div class="project-body">
            <p class="mono-label">{{ project.role }}</p>
            <h3>{{ project.title }}</h3>
            <p class="project-company">{{ project.companyLocation }} / {{ project.period }}</p>
            <p v-html="project.summaryHtml || project.summary"></p>
            <div class="tag-row">
              <span v-for="tag in project.tags.slice(0, 5)" :key="tag">{{ tag }}</span>
            </div>
            <div class="highlight-panel">
              <strong>{{ project.highlightTitle }}</strong>
              <ul>
                <li v-for="item in project.highlights" :key="item">{{ item }}</li>
              </ul>
            </div>
            <div class="card-actions">
              <router-link :to="`/project/${project.slug}`">{{ project.detailLabel || 'Project details' }}</router-link>
              <a
                v-if="project.links.length"
                :href="project.links[0].url"
                target="_blank"
                rel="noopener"
              >
                {{ project.links[0].label }}
              </a>
            </div>
          </div>
        </article>
      </div>
      </section>

      <section class="content-section split-section">
      <div class="section-heading compact">
        <p class="mono-label">Experience</p>
        <h2>Production seniority with hands-on systems depth.</h2>
      </div>
      <div class="experience-rail">
        <article v-for="entry in experience" :key="`${entry.company}-${entry.role}`" class="experience-item">
          <span>{{ entry.date }}</span>
          <h3>{{ entry.role }}</h3>
          <strong>{{ entry.company }}</strong>
          <p>{{ entry.summary }}</p>
        </article>
      </div>
      </section>

      <section class="content-section closing-section">
      <div>
        <p class="mono-label">Two routes, one profile</p>
        <h2>One profile, two useful lenses.</h2>
        <p>
          My work sits where engineering, design, and creative production meet: systems that make ideas buildable,
          testable, and shippable.
        </p>
      </div>
      <div class="closing-actions">
        <router-link class="primary-action" to="/projects">All projects</router-link>
        <a class="ghost-action" href="https://github.com/kvoeten" target="_blank" rel="noopener">GitHub</a>
        <a class="ghost-action" href="https://www.linkedin.com/in/kvoeten/" target="_blank" rel="noopener">LinkedIn</a>
      </div>
      </section>
    </main>
    </div>

    <div
      v-show="showMobileGestureCue"
      class="mobile-gesture-cue"
      :class="`gesture-${mobileGestureMode}`"
      aria-hidden="true"
    >
      <span class="gesture-icon">
        <span class="gesture-rail"></span>
        <span class="gesture-finger"></span>
      </span>
    </div>
  </div>
</template>

<script>
import portfolio from '@/services/portfolio'

export default {
  data: () => ({
    activeTrack: 'engineering',
    heroHoverTrack: null,
    heroSplit: 50,
    isPastHero: false,
    slideTrack: null,
    interactionTrack: 'engineering',
    lastPointerX: null,
    touchStartX: null,
    touchStartY: null,
    touchLastX: null,
    touchLastY: null,
    touchGestureActive: false,
    touchDragTrack: null,
    touchDragDirection: null,
    touchDragOffset: 0,
    lastWheelToggleAt: 0,
    mobileSlideTrack: null,
    mobileSlideDirection: null,
    mobileSlideActive: false,
    mobileSlideTimer: null,
    mobileTrackCommitted: false,
    sidebarWidth: 56,
    viewportWidth: typeof window !== 'undefined' ? window.innerWidth : 1440,
    tracks: portfolio.tracks,
    experience: portfolio.experience
  }),
  computed: {
    trackIds() {
      return ['engineering', 'games']
    },
    isWideDualLayout() {
      return this.viewportWidth >= 1545 && this.hasDesktopPointer()
    },
    isMobileTrackGate() {
      return this.shouldUseMobileTrackMode() && !this.mobileTrackCommitted && !this.isPastHero
    },
    showMobileGestureCue() {
      return this.shouldUseMobileTrackMode() && !this.isPastHero
    },
    mobileGestureMode() {
      return this.isMobileTrackGate ? 'swipe' : 'scroll'
    },
    heroModeClass() {
      if (this.heroHoverTrack) {
        return `focus-${this.heroHoverTrack}`
      }
      return 'is-balanced'
    },
    siteSeamStyle() {
      let seam = this.heroSplit
      if (this.isWideDualLayout) {
        seam = 50
      } else if (this.isPastHero) {
        if (this.slideTrack) {
          seam = 50
        } else {
          seam = this.activeTrack === 'engineering' ? 95 : 5
        }
      }
      const contentWidth = Math.max(0, this.viewportWidth - this.sidebarWidth)
      const seamOffset = contentWidth * (seam / 100)
      const smallestHeroSlice = contentWidth * (this.isWideDualLayout ? 0.5 : 0.4)
      const heroStoryWidth = Math.max(292, Math.min(470, smallestHeroSlice - 96))
      return {
        '--content-width': `${contentWidth}px`,
        '--hero-story-width': `${heroStoryWidth}px`,
        '--layout-sidebar-width': `${this.sidebarWidth}px`,
        '--rail-peek-size': `${contentWidth * 0.05}px`,
        '--site-seam': `${seam}%`,
        '--site-seam-offset': `${seamOffset}px`,
        '--site-seam-fixed': `${this.sidebarWidth + seamOffset}px`,
        '--engineering-story-left': `${contentWidth - (seamOffset / 2)}px`,
        '--games-story-left': `${(contentWidth - seamOffset) / 2}px`,
        '--mobile-drag-x': `${this.touchDragOffset}px`
      }
    },
    siteSlideClass() {
      if (this.mobileSlideTrack && this.mobileSlideDirection) {
        return `mobile-slide mobile-slide-${this.mobileSlideDirection}${this.mobileSlideActive ? ' mobile-slide-active' : ''}`
      }
      if (this.touchDragTrack && this.touchDragDirection) {
        return `mobile-drag mobile-drag-${this.touchDragDirection}`
      }
      if (!this.slideTrack || this.slideTrack === this.activeTrack) {
        return 'slide-rest'
      }
      return `slide-to-${this.slideTrack}`
    },
    currentTrack() {
      return portfolio.getTrack(this.activeTrack)
    },
    featuredProjects() {
      return portfolio.getProjectsForTrack(this.activeTrack).slice(0, 4)
    }
  },
  watch: {
    '$route.query.track': {
      immediate: true,
      handler(track) {
        if (track === 'games' || track === 'engineering') {
          this.activeTrack = track
        }
      }
    }
  },
  methods: {
    trackData(track) {
      return portfolio.getTrack(track)
    },
    projectsForTrack(track) {
      return portfolio.getProjectsForTrack(track).slice(0, 4)
    },
    planeClass(track) {
      return {
        [`${track}-plane`]: true,
        'active-plane': track === this.activeTrack,
        'revealed-plane': track === this.slideTrack || track === this.mobileSlideTrack || track === this.touchDragTrack,
        'background-plane': track !== this.activeTrack
      }
    },
    previewSlideTrack(track) {
      if (this.isWideDualLayout) return
      if (track !== this.activeTrack) {
        this.slideTrack = track
      }
    },
    clearSlidePreview() {
      this.slideTrack = null
    },
    handleShellMouseLeave() {
      this.clearSlidePreview()
      this.resetHeroSplit()
    },
    commitSlideTrack(track) {
      this.setTrack(track)
      this.clearSlidePreview()
    },
    previewTrack(track) {
      this.interactionTrack = track
      if (!this.isWideDualLayout) {
        this.heroHoverTrack = track
      }
    },
    clearHeroPreview() {
      this.heroHoverTrack = null
    },
    hasDesktopPointer() {
      if (typeof window === 'undefined' || !window.matchMedia) return true
      return window.matchMedia('(min-width: 1101px) and (hover: hover) and (pointer: fine)').matches
    },
    shouldUseMobileTrackMode() {
      return this.viewportWidth <= 1100 || !this.hasDesktopPointer()
    },
    trackFromClientX(clientX) {
      const contentWidth = Math.max(0, this.viewportWidth - this.sidebarWidth)
      const midpoint = this.sidebarWidth + (contentWidth / 2)
      return clientX < midpoint ? 'engineering' : 'games'
    },
    updateInteractionIntent(event) {
      if (typeof event.clientX !== 'number') return
      this.lastPointerX = event.clientX
      this.interactionTrack = this.trackFromClientX(event.clientX)
    },
    updateTouchIntent(event) {
      const touch = event.touches && event.touches[0]
      if (!touch) return
      this.lastPointerX = touch.clientX
      this.interactionTrack = this.trackFromClientX(touch.clientX)
    },
    applyTrackIntent(track) {
      this.interactionTrack = track
      if (!this.isWideDualLayout) {
        this.heroHoverTrack = track
      }
      if (!this.isPastHero && !this.isWideDualLayout) {
        this.heroSplit = track === 'engineering' ? 60 : 40
      }
      this.setTrack(track, { animate: this.shouldUseMobileTrackMode() })
      this.clearSlidePreview()
    },
    trackFromSwipeDelta(deltaX) {
      return deltaX < 0 ? 'games' : 'engineering'
    },
    trackFromWheelDelta(deltaX) {
      return deltaX > 0 ? 'games' : 'engineering'
    },
    handleTouchStart(event) {
      const touch = event.touches && event.touches[0]
      if (!touch) return
      this.touchStartX = touch.clientX
      this.touchStartY = touch.clientY
      this.touchLastX = touch.clientX
      this.touchLastY = touch.clientY
      this.touchGestureActive = true
      this.updateTouchIntent(event)
    },
    handleTouchMove(event) {
      const touch = event.touches && event.touches[0]
      if (!touch) return
      this.touchLastX = touch.clientX
      this.touchLastY = touch.clientY
      this.updateTouchIntent(event)
      this.updateTouchDragPreview(event)
    },
    handleTouchEnd() {
      if (!this.touchGestureActive || this.touchStartX === null || this.touchLastX === null) {
        this.resetTouchGesture()
        return
      }
      const deltaX = this.touchLastX - this.touchStartX
      const deltaY = (this.touchLastY || 0) - (this.touchStartY || 0)
      const isHorizontalSwipe = Math.abs(deltaX) > 48 && Math.abs(deltaX) > Math.abs(deltaY) * 1.25
      const targetTrack = this.trackFromSwipeDelta(deltaX)
      if (this.isMobileTrackGate) {
        if (isHorizontalSwipe) {
          this.completeTouchSlide(targetTrack)
        } else {
          this.resetHeroSplit()
        }
        this.resetTouchGesture()
        return
      }
      if (isHorizontalSwipe && targetTrack !== this.activeTrack) {
        this.completeTouchSlide(targetTrack)
        this.resetTouchGesture()
        return
      }
      this.resetTouchGesture()
    },
    resetTouchGesture() {
      this.touchStartX = null
      this.touchStartY = null
      this.touchLastX = null
      this.touchLastY = null
      this.touchGestureActive = false
      this.touchDragTrack = null
      this.touchDragDirection = null
      this.touchDragOffset = 0
    },
    updateTouchDragPreview(event) {
      if (!this.touchGestureActive || this.touchStartX === null || this.touchLastX === null) return
      if (!this.shouldUseMobileTrackMode()) return
      const deltaX = this.touchLastX - this.touchStartX
      const deltaY = (this.touchLastY || 0) - (this.touchStartY || 0)
      const isHorizontalDrag = Math.abs(deltaX) > 10 && Math.abs(deltaX) > Math.abs(deltaY) * 1.12
      const targetTrack = this.trackFromSwipeDelta(deltaX)
      if (this.isMobileTrackGate) {
        event.preventDefault()
        if (!isHorizontalDrag) return
        const contentWidth = Math.max(1, this.viewportWidth - this.sidebarWidth)
        const dragPercent = (deltaX / contentWidth) * 50
        this.heroSplit = Math.max(24, Math.min(76, 50 + dragPercent))
        this.touchDragTrack = targetTrack
        this.touchDragDirection = targetTrack === 'games' ? 'to-games' : 'to-engineering'
        this.touchDragOffset = deltaX
        return
      }
      if (!isHorizontalDrag) return
      if (targetTrack === this.activeTrack) {
        this.touchDragTrack = null
        this.touchDragDirection = null
        this.touchDragOffset = 0
        return
      }
      const direction = this.trackDirection(this.activeTrack, targetTrack)
      if (!direction) return
      const maxOffset = Math.max(1, this.viewportWidth)
      this.touchDragTrack = targetTrack
      this.touchDragDirection = direction
      this.touchDragOffset = direction === 'to-games'
        ? Math.max(deltaX, -maxOffset)
        : Math.min(deltaX, maxOffset)
      event.preventDefault()
    },
    completeTouchSlide(track) {
      const direction = this.isMobileTrackGate
        ? (track === 'games' ? 'to-games' : 'to-engineering')
        : this.trackDirection(this.activeTrack, track)
      if (!direction) return
      this.interactionTrack = track
      this.heroHoverTrack = track
      window.clearTimeout(this.mobileSlideTimer)
      this.mobileSlideTrack = track
      this.mobileSlideDirection = direction
      this.mobileSlideActive = true
      this.mobileSlideTimer = window.setTimeout(() => {
        this.activeTrack = track
        this.mobileTrackCommitted = true
        this.heroSplit = 50
        this.updateTrackUrl(track)
        this.mobileSlideTrack = null
        this.mobileSlideDirection = null
        this.mobileSlideActive = false
      }, 430)
    },
    handleWheel(event) {
      this.updateInteractionIntent(event)
      if (this.isWideDualLayout) return
      const isHorizontalWheel = Math.abs(event.deltaX) > 24 && Math.abs(event.deltaX) > Math.abs(event.deltaY) * 1.25
      if (!isHorizontalWheel) return
      const now = Date.now()
      if (now - this.lastWheelToggleAt < 520) return
      this.lastWheelToggleAt = now
      this.applyTrackIntent(this.trackFromWheelDelta(event.deltaX))
    },
    updateHeroSplit(event) {
      this.updateInteractionIntent(event)
      if (!this.hasDesktopPointer()) return
      if (this.isWideDualLayout) {
        this.heroSplit = 50
        this.clearHeroPreview()
        return
      }
      if (this.isPastHero) return
      const track = this.trackFromClientX(event.clientX)
      this.heroSplit = track === 'engineering' ? 60 : 40
      this.heroHoverTrack = track
    },
    resetHeroSplit() {
      this.heroSplit = 50
      this.clearHeroPreview()
    },
    exploreTrack(track) {
      this.setTrack(track)
      this.$nextTick(() => {
        const target = document.getElementById('featured')
        if (target) {
          target.scrollIntoView({ behavior: 'smooth', block: 'start' })
        }
      })
    },
    trackDirection(fromTrack, toTrack) {
      if (fromTrack === 'engineering' && toTrack === 'games') return 'to-games'
      if (fromTrack === 'games' && toTrack === 'engineering') return 'to-engineering'
      return null
    },
    updateTrackUrl(track) {
      if (typeof window === 'undefined') return
      const query = new URLSearchParams(window.location.search)
      if (query.get('track') === track) return
      query.set('track', track)
      const nextUrl = `${window.location.pathname}?${query.toString()}${window.location.hash}`
      window.history.replaceState(window.history.state, '', nextUrl)
    },
    setTrack(track, options = {}) {
      if (track !== 'games' && track !== 'engineering') return
      if (track === this.activeTrack) {
        this.updateTrackUrl(track)
        return
      }

      const direction = this.trackDirection(this.activeTrack, track)
      if (options.animate && direction) {
        window.clearTimeout(this.mobileSlideTimer)
        this.mobileSlideTrack = track
        this.mobileSlideDirection = direction
        this.mobileSlideActive = false
        this.$nextTick(() => {
          if (this.mobileSlideTrack !== track) return
          void this.$el.offsetHeight
          window.requestAnimationFrame(() => {
            this.mobileSlideActive = true
          })
        })
        this.mobileSlideTimer = window.setTimeout(() => {
          this.activeTrack = track
          this.updateTrackUrl(track)
          this.mobileSlideTrack = null
          this.mobileSlideDirection = null
          this.mobileSlideActive = false
        }, 430)
        return
      }

      this.activeTrack = track
      this.updateTrackUrl(track)
    },
    updateScrollState() {
      if (typeof window === 'undefined') return
      const wasPastHero = this.isPastHero
      const isPastHero = window.scrollY > window.innerHeight * 0.72
      if (isPastHero && !wasPastHero && !this.isWideDualLayout) {
        const inferredTrack = this.hasDesktopPointer()
          ? (this.heroHoverTrack || this.interactionTrack || this.activeTrack)
          : this.activeTrack
        this.setTrack(inferredTrack)
        this.clearSlidePreview()
      }
      this.isPastHero = isPastHero
    },
    updateViewportMetrics() {
      if (typeof window === 'undefined') return
      this.viewportWidth = window.innerWidth
    }
  },
  mounted() {
    this.updateViewportMetrics()
    this.updateScrollState()
    window.addEventListener('scroll', this.updateScrollState, { passive: true })
    window.addEventListener('resize', this.updateViewportMetrics, { passive: true })
  },
  beforeDestroy() {
    if (typeof window === 'undefined') return
    window.clearTimeout(this.mobileSlideTimer)
    window.removeEventListener('scroll', this.updateScrollState)
    window.removeEventListener('resize', this.updateViewportMetrics)
  }
}
</script>

<style scoped>
.portfolio-shell {
  --rail-peek: 5vw;
  --hero-story-width: min(470px, calc(40vw - 96px));
  --game-accent: #d84f45;
  --game-accent-rgb: 216, 79, 69;
  --game-accent-on: #170b0c;
  --game-accent-soft: #ffc0b8;
  --game-accent-shadow: #64211d;
  position: relative;
  min-height: 100vh;
  width: 100%;
  box-sizing: border-box;
  overflow-x: hidden;
  background:
    var(--palette-bg);
  color: var(--palette-text);
  font-family: "JetBrains Mono", monteserrat, monospace;
  touch-action: pan-y;
}

.portfolio-shell::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  background:
    linear-gradient(180deg, rgba(var(--palette-bg-rgb), 0.4), rgba(var(--palette-bg-rgb), 0.74) 64%, rgba(var(--palette-bg-rgb), 0.9)),
    url("../../public/images/landing/landing-backdrop-new.png") center center / cover no-repeat;
  opacity: 1;
  pointer-events: none;
}

.site-stack {
  position: relative;
  z-index: 1;
  display: grid;
  min-height: 100vh;
  overflow: hidden;
}

.site-plane {
  position: relative;
  grid-area: 1 / 1;
  min-height: 100vh;
  box-sizing: border-box;
  background: transparent;
  transform: translateX(0);
  transition:
    transform 620ms cubic-bezier(0.2, 0.78, 0.18, 1),
    box-shadow 620ms ease,
    opacity 260ms ease;
  will-change: transform;
}

.engineering-plane {
